import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-110: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short110', durationInSeconds: 36.6, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(4.6);
const C2 = secToFrame(13.0);
const C3 = secToFrame(18.5);
const C4 = secToFrame(23.3);
const C5 = secToFrame(31.0);
const CTA = secToFrame(33.2);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short110: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-110/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="CACHE PRICING" lines={[{ text: 'SAME 15¢ INPUT' },{ text: '5X APART', accent: true }]} />
      </FadeOut>
      <FadeOut at={C2}>
        <ToolCard name="Both: 15¢ input" tagline="DeepSeek Flash + MiniMax Flash." chip="15¢" at={B1 + 4}>
          <Panel>
            <Line k="DeepSeek off-peak" v="$0.15" good />
            <Line k="MiniMax M3.1" v="$0.15" good />
            <Line k="Output, both" v="$0.60" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={C3}>
        <ToolCard name="DeepSeek cache hit" tagline="Off-peak." chip="0.3¢" at={C2 + 4}>
          <Panel>
            <Line k="Cache hit / 1M" v="$0.003" good />
            <Line k="At peak" v="$0.006" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={C4}>
        <ToolCard name="MiniMax cache hit" tagline="Flat price." chip="1.5¢" at={C3 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Cache hit / 1M" v="$0.015" bad />
            <Line k="vs DeepSeek" v="5x" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={C5}>
        <ToolCard name="DeepSeek at peak" tagline="Weekdays, UTC." chip="PEAK" at={C4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Hours" v="01-04, 06-10" />
            <Line k="Cache hit" v="$0.006" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Price only" tagline="Quality not compared." chip="FINE PRINT" at={C5 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="DeepSeek cache" v="$0.003" good />
            <Line k="MiniMax cache" v="$0.015" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-110/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CACHE PRICING" lines={[{ text: 'SAME 15¢ INPUT' },{ text: '5X APART', accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Same 15¢. Five times apart.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short110;
